from h34 import *
M=mcq;F=tf;S=short
b='<circle cx="150" cy="150" r="120" fill="#fff" stroke="#333" stroke-width="3"/>'
import math
data=[("Sleeping",8,"#5c6bc0"),("Eating",2,"#ef6c00"),("Studying",6,"#43a047"),("Playing",2,"#fdd835"),("Helping parents",2,"#26a69a"),("Watching TV",1,"#8d6e63"),("Toilet",1,"#90a4ae"),("Other",2,"#ec407a")]
a=-90.0
for n,h,c in data:
    s=math.radians(a);e=math.radians(a+h*15);a+=h*15
    x1=150+120*math.cos(s);y1=150+120*math.sin(s);x2=150+120*math.cos(e);y2=150+120*math.sin(e)
    b+=f'<path d="M150 150 L{x1:.1f} {y1:.1f} A120 120 0 {1 if h>12 else 0} 1 {x2:.1f} {y2:.1f} Z" fill="{c}" stroke="#fff" stroke-width="2"/>'
for i,(n,h,c) in enumerate(data):
    b+=f'<rect x="320" y="{40+i*28}" width="18" height="18" fill="{c}"/><text x="346" y="{54+i*28}" font-size="15">{n}: {h} hours</text>'
b+='<text x="150" y="290" text-anchor="middle" font-size="13">Moyna\'s 24-hour circle</text>'
svgfile('c3-day-circle.svg',560,300,b)
chapter(3,'evs','staying-healthy-and-happy','Staying Healthy and Happy',
 ("Healthy and happy","We want our bodies and minds to work properly, so we must keep them healthy. In this chapter we learn simple habits that keep us clean, active, safe and happy."),
 [("Clean and bright",["Ask yourself some questions: Did I brush my teeth today? Did I take a shower? Did I comb my hair?","Did I wash my hands with soap, and are my nails trimmed and clean?","These simple habits keep our bodies clean and free from diseases.","They keep our bodies and minds healthy and happy."]),
  ("Our daily routine",["Write down what you do every day, from the time you wake up till you go to sleep.","A good routine has a shower, washing hands with soap, brushing teeth, eating food, and playing outside.","It also has 6 to 8 glasses of water and at least 8 hours of sleep in total.","We should brush twice a day, once after waking up and once before going to bed.","We should rinse our mouth after eating and wash hands with soap after using the toilet and after coming home from outside.","If the answer to any of these is No, think and talk about how to make it a habit, and what makes it difficult."]),
  ("How do we brush our teeth?",["Moyna's Dadu cleans his teeth with a twig from a neem or babool tree.","He chews the twig to make a brush, removes food stuck between teeth, and gives his gums a good massage.","Moyna found neem bitter, but babool tasted better.","The modern idea of brushing teeth came from the Indian tradition of datun, using twigs of neem, karanj, babool and other plants.","We can ask grandparents what they used to wash hair, body and clothes when they were young, such as reetha or shikakai for hair."]),
  ("A home-cleaner from peels",["We can make an eco-friendly cleaner at home from orange or lemon peels.","Fill a half-litre transparent container with peels, add cloves or bay leaves if you like, and cover with white vinegar.","Keep it in a sunny place for about two weeks and shake it now and then.","Then strain the liquid, and mix a cup of it in a bucket of water to clean floors and bathrooms."]),
  ("Animals keep clean too",["Monkeys sit and groom each other to keep their bodies free from insects.","Birds use their beaks to clean their feathers.","We can observe how other animals and insects clean themselves."]),
  ("Playing and exercise",["When we run fast, we breathe faster and deeper, our cheeks turn red, and we feel warm and sweat.","This is because exercise makes our heart work harder and better.","Exercise is good for the body, and there are many ways to do it, like walking like a duck, jumping like a frog or running like a cat.","Skipping with a rope is fun, and we can count our jumps or say a rhyme.","Harpreet's grandmother cannot move much because of knee pain, but she walks a little and plays chess, because both mind and body should be active."]),
  ("Playing safely",["It is important to be safe while having fun.","A park or a school ground is a safe place to play.","A busy road, a roof without railings and a construction site are unsafe.","In public places there may be strangers, so do not go with or take things from strangers unless a parent or trusted adult is with you.","Parents may fix a secret password if they send someone new to pick you up.","Pay attention to your surroundings while playing."]),
  ("Know what your body needs",["Feelings like sleepy, hungry or tired are the body's way of telling us something is not right.","We all have different needs, so track your activities for a week and see how you feel.","Note the pattern between good sleep, food and exercise and feeling good.","You can draw a 24-slice circle for a day, one slice for each hour, and colour it by your activities.","Moyna sleeps 8 hours, eats 2, studies 6, plays 2, helps parents 2, watches TV 1, uses the toilet 1 and spends 2 on other things."])],
 [("Moyna's circle has 24 slices. Sleeping 8, eating 2, studying 6, playing 2. How many hours are these four?",[("Add 8 + 2 + 6 + 2.","Find the total of the four activities."),("8 + 2 = 10, then 10 + 6 = 16, then 16 + 2 = 18.","Add step by step."),("So these four take 18 hours of the 24.","The rest, 6 hours, goes to other activities.")]),
  ("Is it safe to play on a roof without railings?",[("Think about falling.","Without railings a fall is possible."),("So it is unsafe.","A park or school ground is safer.")]),
  ("A stranger says your mother sent him to take you home. What do you do?",[("Do not go with him.","Never go with strangers."),("Say No, I know my way home, and tell a trusted adult.","Parents use a password if they send someone.")])],
 ("Tell a friend three habits that keep us healthy and happy.",["Brush teeth twice a day and wash hands with soap","Drink water, eat well and sleep at least 8 hours","Play and exercise","Be safe and careful with strangers"],["Only studying keeps us healthy","Sleep is not needed","Strangers are always safe"]),
 ["Clean habits like brushing, bathing and washing hands keep us free from diseases.","We need 6 to 8 glasses of water, good food and at least 8 hours of sleep.","Exercise makes the heart work better.","Play in safe places and be careful with strangers.","Our feelings tell us what our body needs."],
 [M("sh-1",1,"How many times a day should we brush our teeth?","Twice",[("Once a week","That is too little."),("Never","Teeth need daily care."),("Ten times","Twice is enough.")],"Brush after waking up and before bed.",None),
  M("sh-2",1,"Which twig did Moyna's Dadu use to clean his teeth?","Neem or babool",[("Mango","The text names neem and babool."),("Bamboo","The text names neem and babool."),("Rose","The text names neem and babool.")],"This old way is called datun.",None),
  F("sh-3",1,"We should wash our hands with soap after using the toilet.",True,"It removes germs."),
  M("sh-4",1,"How many hours of sleep do we need in total?","At least 8",[("2","That is too little."),("4","That is too little."),("12 every day with no play","At least 8 is the guide.")],"Sleep helps the body and mind work well.",None),
  M("sh-5",2,"Why do we breathe faster when we run?","Exercise makes our heart work harder",[("The heart stops","The heart works harder."),("We are sleepy","We are active."),("It is cold","It is because of exercise.")],"Exercise is good for the body.",None),
  M("sh-6",2,"Which is a safe place to play?","A school ground",[("A busy road","Vehicles can hurt us."),("A construction site","It is dangerous."),("A roof without railings","We may fall.")],"Choose safe places.",None),
  S("sh-7",2,"Monkeys groom each other to keep free from ____.",["insects","insect"],"Grooming removes insects.",[("water","They remove insects.")]),
  M("sh-8",2,"A stranger offers sweets and a ride. What should you do?","Say no and tell a trusted adult",[("Go with him","Never go with strangers."),("Take the sweets","Do not take things from strangers."),("Keep it a secret","Tell a trusted adult.")],"Do not interact with strangers without a trusted adult.",None),
  F("sh-9",2,"Feelings like feeling sleepy or tired are the body's way of telling us something.",True,"We should listen to our body."),
  M("sh-10",3,"What do we mix with orange peels to make a home cleaner?","White vinegar",[("Sugar","The recipe uses vinegar."),("Milk","The recipe uses vinegar."),("Oil","The recipe uses vinegar.")],"Keep it in the sun for two weeks.",None),
  M("sh-11",3,"Moyna's circle has 24 slices. Why 24?","One slice for each hour of the day",[("Days in a month","A day has 24 hours."),("Number of teeth","A day has 24 hours."),("Number of friends","A day has 24 hours.")],"We colour slices by activity.",None),
  S("sh-12",3,"The old Indian way of cleaning teeth with twigs is called ____.",["datun","Datun"],"Datun inspired modern brushing.",[("shampoo","Datun is the twig tradition.")])],
 svgs=[("c3-day-circle","A circle of 24 hours divided by activities","Moyna's day: sleep 8, eat 2, study 6, play 2, help 2, TV 1, toilet 1, other 2.")])
